    private final SheetRoleRepository roles;
    private final SheetRepository sheetRows;
    private final SheetService sheets;
    private final Rollup rollup;
    private final ApplicationEventPublisher events;

    public AccessService(SheetRoleRepository roles, SheetRepository sheetRows, SheetService sheets,
            Rollup rollup, ApplicationEventPublisher events) {
        this.rollup = rollup;
        this.roles = roles;
        this.sheetRows = sheetRows;
        this.sheets = sheets;
        this.events = events;
    }

    /** The roles set on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserName(sheetId);
    }

    /** The user's role on the sheet: clerk unless one was set. */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUserName(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return sheetRows.findById(sheetId).map(Sheet::getClerkLimit).orElse(null);
    }

    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return sheets.floor(sheetId);
    }

    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return sheets.terms(sheetId);
    }

    /** The grade's own terms; null when it has none (it uses the sheet's). */
    @Transactional(readOnly = true)
    public Integer gradeTerms(String sheetId, String grade) {
        return sheetRows.findById(sheetId).map(s -> s.getGradeTerms(grade)).orElse(null);
    }

    @Transactional(readOnly = true)
    public BigDecimal latePct(String sheetId) {
        return sheets.latePct(sheetId);
    }

    /** The sheet's policy date as set; null when blank. */
    @Transactional(readOnly = true)
    public LocalDate policyDate(String sheetId) {
        return sheets.policyDate(sheetId);
    }

    /** The sheet's period numbering from as set; null when blank (off). */
    @Transactional(readOnly = true)
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.periodNumberingFrom(sheetId);
    }

    /** Give a user name a role on the sheet, replacing the one it had. */
    @Transactional
    public SheetRole setRole(String sheetId, String user, String name, Role role) {
        sheets.load(sheetId, user);
        SheetRole row = roles.findBySheetIdAndUserName(sheetId, name).orElse(null);
        if (row == null) {
            row = roles.saveAndFlush(new SheetRole(sheetId, name, role));
        } else {
            row.setRole(role);
            roles.flush();
        }
        events.publishEvent(new RoleSet(sheetId, user, name, role.key()));
        return row;
    }

    /**
     * Save the settings given, as written (blank: none, or the default), in one change; a setting left
     * out (null) is kept as it is.
     */
    @Transactional
    public void setSettings(String sheetId, String user, String clerkLimit, String floor, String terms,
            Map<String, String> gradeTerms, String latePct, String policyDate, String periodNumberingFrom) {
        if (clerkLimit != null) {
            setClerkLimit(sheetId, user, clerkLimit.isEmpty() ? null : new BigDecimal(clerkLimit));
        }
        if (floor != null) {
            setFloor(sheetId, user, floor.isEmpty() ? null : new BigDecimal(floor));
        }
        if (terms != null) {
            setTerms(sheetId, user, terms.isEmpty() ? null : Integer.valueOf(terms));
        }
        gradeTerms.forEach((grade, days) -> {
            if (days != null) {
                setGradeTerms(sheetId, user, grade, days.isEmpty() ? null : Integer.valueOf(days));
            }
        });
        if (latePct != null) {
            setLatePct(sheetId, user, latePct.isEmpty() ? null : new BigDecimal(latePct));
        }
        if (policyDate != null) {
            setPolicyDate(sheetId, user, policyDate.isEmpty() ? null : LocalDate.parse(policyDate));
        }
        if (periodNumberingFrom != null) {
            setPeriodNumberingFrom(sheetId, user,
                    periodNumberingFrom.isEmpty() ? null : LocalDate.parse(periodNumberingFrom));
        }
    }

    /**
     * Save the sheet's terms in days; null puts back the ones a sheet starts with. A claim added from
     * then on whose grade has no terms of its own is due by its date plus them; a claim already added
     * keeps the due-by it has.
     */
    @Transactional
    public int setTerms(String sheetId, String user, Integer terms) {
        Sheet sheet = sheets.load(sheetId, user);
        int days = terms == null ? Sheet.DEFAULT_TERMS : terms;
        sheet.setTerms(days);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, TERMS, Integer.toString(days)));
        return days;
    }

    /**
     * Save a grade's own terms in days; null removes them, the grade then using the sheet's terms. A
     * claim added from then on whose person has the grade on its date is due by its date plus them; a
     * claim already added keeps the due-by it has.
     */
    @Transactional
    public Integer setGradeTerms(String sheetId, String user, String grade, Integer days) {
        Sheet sheet = sheets.load(sheetId, user);
        sheet.setGradeTerms(grade, days);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, gradeTermsKey(grade), days == null ? "" : days.toString()));
        return days;
    }

    /**
     * Save the sheet's late percent; null puts back the one a sheet starts with (0.00). Every late charge
     * not yet settled moves with it; a settled due keeps the one it had.
     */
    @Transactional
    public BigDecimal setLatePct(String sheetId, String user, BigDecimal latePct) {
        Sheet sheet = sheets.load(sheetId, user);
        BigDecimal scaled = latePct == null ? Sheet.DEFAULT_LATE_PCT : latePct.setScale(2, RoundingMode.HALF_UP);
        Rollup.Figures before = rollup.figures(sheetId);
        sheet.setLatePct(scaled);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, LATE_PCT, scaled.toPlainString()));
        rollup.changed(sheetId, user, before);
        return scaled;
    }

    /**
     * Save the sheet's policy date; null leaves it blank (the sheet's today). Every live figure rounds
     * by it; a settled or stated figure keeps the one it had.
     */
    @Transactional
    public LocalDate setPolicyDate(String sheetId, String user, LocalDate policyDate) {
        Sheet sheet = sheets.load(sheetId, user);
        Rollup.Figures before = rollup.figures(sheetId);
        sheet.setPolicyDate(policyDate);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, POLICY_DATE, policyDate == null ? "" : policyDate.toString()));
        rollup.changed(sheetId, user, before);
        return policyDate;
    }

    /**
     * Save the sheet's period numbering from; null turns period numbering off. Claims already opened
     * keep the numbers they have.
     */
    @Transactional
    public LocalDate setPeriodNumberingFrom(String sheetId, String user, LocalDate from) {
        Sheet sheet = sheets.load(sheetId, user);
        sheet.setPeriodNumberingFrom(from);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, PERIOD_NUMBERING_FROM, from == null ? "" : from.toString()));
        return from;
    }

    /** Save the sheet's clerk limit; null removes it. */
    @Transactional
    public BigDecimal setClerkLimit(String sheetId, String user, BigDecimal limit) {
        Sheet sheet = sheets.load(sheetId, user);
        BigDecimal scaled = limit == null ? null : limit.setScale(2, RoundingMode.HALF_UP);
        sheet.setClerkLimit(scaled);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, CLERK_LIMIT, scaled == null ? "" : scaled.toPlainString()));
        return scaled;
    }

    /**
     * Save the sheet's floor; null puts back the one a sheet starts with. Every live due moves with it;
     * a settled, stated or closed figure keeps the one it had.
     */
    @Transactional
    public BigDecimal setFloor(String sheetId, String user, BigDecimal floor) {
        Sheet sheet = sheets.load(sheetId, user);
        BigDecimal scaled = floor == null ? Sheet.DEFAULT_FLOOR : floor.setScale(2, RoundingMode.HALF_UP);
        Rollup.Figures before = rollup.figures(sheetId);
        sheet.setFloor(scaled);
        sheetRows.saveAndFlush(sheet);
        events.publishEvent(new SettingChanged(sheetId, user, FLOOR, scaled.toPlainString()));
        rollup.changed(sheetId, user, before);
        return scaled;
    }

    /**
     * Whether the user may settle a claim of the given due outright: a steward settles anything, a clerk
     * a due up to the clerk limit (a due of n/a, null, is within any limit). A clerk's settle above it
     * leaves the claim PENDING for a steward.
     */
    @Transactional(readOnly = true)
    public boolean canSettle(String sheetId, String user, BigDecimal due) {
        if (due == null) {
            return true;
        }
        BigDecimal limit = clerkLimit(sheetId);
        return limit == null || due.compareTo(limit) <= 0 || roleOf(sheetId, user) != Role.CLERK;
    }
}
package net.officefloor.hq.app.access;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** A sheet's roles and settings. The signed-in user's name comes in the {@code X-User} header. */
@RestController
@RequestMapping("/api/sheets/{sheetId}")
@Validated
public class AccessController {

    public record RoleView(String user, String role) {

        static RoleView of(SheetRole r) {
            return new RoleView(r.getUserName(), r.getRole().key());
        }
    }

    /**
     * The sheet's settings as shown; a limit is a figure with two decimals, null for none; so is the floor;
     * the terms are a number of days, and so are the terms of grades A, B and C, null for a grade without
     * its own (it uses the sheet's); the late percent is a figure with two decimals; the policy date and
     * the period numbering from are dates (yyyy-mm-dd), null when blank.
     */
    public record SettingsView(String clerkLimit, String floor, String terms, String termsA, String termsB,
            String termsC, String latePct, String policyDate, String periodNumberingFrom) {

        static SettingsView of(BigDecimal limit, BigDecimal floor, int terms, Integer termsA, Integer termsB,
                Integer termsC, BigDecimal latePct, LocalDate policyDate, LocalDate periodNumberingFrom) {
            return new SettingsView(limit == null ? null : limit.toPlainString(), floor.toPlainString(),
                    Integer.toString(terms), termsA == null ? null : termsA.toString(),
                    termsB == null ? null : termsB.toString(), termsC == null ? null : termsC.toString(),
                    latePct.toPlainString(),
                    policyDate == null ? null : policyDate.toString(),
                    periodNumberingFrom == null ? null : periodNumberingFrom.toString());
        }
    }

    public record AccessView(List<RoleView> roles, SettingsView settings) {
    }

    /** A user name and a role: clerk or steward. */
    public record RoleForm(@NotBlank @Size(max = 200) String user, @NotNull @Pattern(regexp = "clerk|steward") String role) {
    }

    /**
     * The settings to save; one left out (null) is kept as it is. A clerk limit is 0.00 or more with up
     * to two decimals, blank meaning no limit; so is a floor, blank putting back 1.00. The terms are a
     * whole number of days, blank putting back 14; so are a grade's own terms, blank removing them (the
     * grade then uses the sheet's). The late percent is 0.00 or more with up to two
     * decimals, blank putting back 0.00. The policy date is a date (yyyy-mm-dd), blank meaning the
     * sheet's today. The period numbering from is a date (yyyy-mm-dd), blank meaning off.
     */
    public record SettingsForm(@Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String clerkLimit,
            @Pattern(regexp = "(\\d{1,12}(\\.\\d{1,2})?)?") String floor,
            @Pattern(regexp = "(\\d{1,5})?") String terms,
            @Pattern(regexp = "(\\d{1,5})?") String termsA,
            @Pattern(regexp = "(\\d{1,5})?") String termsB,
            @Pattern(regexp = "(\\d{1,5})?") String termsC,
            @Pattern(regexp = "(\\d{1,10}(\\.\\d{1,2})?)?") String latePct,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String policyDate,
            @Pattern(regexp = "(\\d{4}-\\d{2}-\\d{2})?") String periodNumberingFrom) {
    }

    private final AccessService service;

    public AccessController(AccessService service) {
        this.service = service;
    }

    @GetMapping("/access")
    public AccessView get(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        String sheet = sheetId.trim();
        return new AccessView(service.roles(sheet).stream().map(RoleView::of).toList(),
                settings(sheet));
    }

    @PutMapping("/roles")
    public RoleView setRole(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody RoleForm form) {
        Role role = Role.of(form.role()).orElseThrow();
        return RoleView.of(service.setRole(sheetId.trim(), user.trim(), form.user().trim(), role));
    }

    @PutMapping("/settings")
    public SettingsView setSettings(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank String user, @Valid @RequestBody SettingsForm form) {
        String sheet = sheetId.trim();
        Map<String, String> gradeTerms = new LinkedHashMap<>();
        gradeTerms.put("A", form.termsA());
        gradeTerms.put("B", form.termsB());
        gradeTerms.put("C", form.termsC());
        service.setSettings(sheet, user.trim(), form.clerkLimit(), form.floor(), form.terms(), gradeTerms,
                form.latePct(), form.policyDate(), form.periodNumberingFrom());
        return settings(sheet);
    }

    private SettingsView settings(String sheet) {
        return SettingsView.of(service.clerkLimit(sheet), service.floor(sheet), service.terms(sheet),
                service.gradeTerms(sheet, "A"), service.gradeTerms(sheet, "B"), service.gradeTerms(sheet, "C"),
                service.latePct(sheet), service.policyDate(sheet), service.periodNumberingFrom(sheet));
    }

    /** A policy date or period numbering from that is no date on the calendar: the save is refused and changes nothing. */
    @ExceptionHandler(DateTimeParseException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void noSuchDate() {
    }

    /** Another user set a role for the same name at the same moment: this one is refused. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void roleTaken() {
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet, keyed by the id a user types; created the first time it is loaded. */
@Entity
@Table(name = "sheet")
public class Sheet {

    /** The floor a sheet starts with. */
    public static final BigDecimal DEFAULT_FLOOR = new BigDecimal("1.00");

    /** The terms a sheet starts with, in days. */
    public static final int DEFAULT_TERMS = 14;

    /** The late percent a sheet starts with. */
    public static final BigDecimal DEFAULT_LATE_PCT = new BigDecimal("0.00");

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's today: the date every date-dependent decision on the sheet uses. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The number given to the last claim opened on the sheet; 0 before any is opened. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** The most due a clerk may settle on a claim; null when there is no limit. */
    @Column(name = "clerk_limit", precision = 14, scale = 2)
    private BigDecimal clerkLimit;

    /** The least live due a claim has; 1.00 until set. */
    @Column(name = "due_floor", nullable = false, precision = 14, scale = 2)
    private BigDecimal floor = DEFAULT_FLOOR;

    /** The days a claim has to be paid by, from its date; 14 until set. */
    @Column(name = "terms", nullable = false)
    private int terms = DEFAULT_TERMS;

    /** The days a claim of grade A, B or C has to be paid by, from its date; null: the sheet's terms. */
    @Column(name = "terms_a")
    private Integer termsA;

    @Column(name = "terms_b")
    private Integer termsB;

    @Column(name = "terms_c")
    private Integer termsC;

    /** The percent of its figure an overdue claim's due gains for every full 30 days overdue; 0.00 until set. */
    @Column(name = "late_pct", nullable = false, precision = 14, scale = 2)
    private BigDecimal latePct = DEFAULT_LATE_PCT;

    /** The date a claim's rounding turns on: half up before it, half to even on or after it; null: the sheet's today. */
    @Column(name = "policy_date")
    private LocalDate policyDate;

    /** From the sheet's today on this date, a claim opened is numbered within its period; null: off. */
    @Column(name = "period_numbering_from")
    private LocalDate periodNumberingFrom;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    public BigDecimal getFloor() {
        return floor;
    }

    public void setFloor(BigDecimal floor) {
        this.floor = floor;
    }

    public int getTerms() {
        return terms;
    }

    public void setTerms(int terms) {
        this.terms = terms;
    }

    /** The grade's own terms; null when it has none (it uses the sheet's terms). */
    public Integer getGradeTerms(String grade) {
        return switch (grade) {
            case "A" -> termsA;
            case "B" -> termsB;
            case "C" -> termsC;
            default -> null;
        };
    }

    /** Set the grade's own terms; null removes them (it uses the sheet's terms). */
    public void setGradeTerms(String grade, Integer days) {
        switch (grade) {
            case "A" -> termsA = days;
            case "B" -> termsB = days;
            case "C" -> termsC = days;
            default -> throw new IllegalArgumentException("No such grade " + grade);
        }
    }

    /** The terms in force for a claim of the grade: its own, or the sheet's when it has none. */
    public int termsFor(String grade) {
        Integer own = grade == null ? null : getGradeTerms(grade);
        return own != null ? own : terms;
    }

    public LocalDate getPolicyDate() {
        return policyDate;
    }

    public void setPolicyDate(LocalDate policyDate) {
        this.policyDate = policyDate;
    }

    public LocalDate getPeriodNumberingFrom() {
        return periodNumberingFrom;
    }

    public void setPeriodNumberingFrom(LocalDate periodNumberingFrom) {
        this.periodNumberingFrom = periodNumberingFrom;
    }

    public BigDecimal getLatePct() {
        return latePct;
    }

    public void setLatePct(BigDecimal latePct) {
        this.latePct = latePct;
    }
}

